test('pursuit tracks live destinations without canceling charge/shot/swing and keeps spatial recovery clock',()=>{const c=new CPUController(23),n=c.navigation as any;for(const mode of['charge','shot','hold','flight']){n.mode=mode;n.until=220;n.progressTick=12;n.link={land:{x:4,y:3}};const link=n.link;c.navigation.continueTo({x:14,y:12});c.navigation.chase(1);c.navigation.continueTo({x:22,y:8});c.navigation.chase(1);assert.deepEqual(c.navigation.goal,{x:22,y:8});assert.equal(n.mode,mode);assert.equal(n.until,220);assert.equal(n.progressTick,12);assert.equal(n.link,link);}});
test('real inputs close on a moving human target and continue after elevation changes',()=>{for(const elevation of[false,true]){const r=chase(false,elevation);assert.ok(r.best<1);assert.ok(r.contact!==undefined);assert.ok(r.nearSeconds>5);if(elevation)assert.ok(r.nav.charges+r.nav.attachments>0);}});
test('repeat spring landings escape via ordinary input across lily, sponge and cushion surfaces',()=>{for(const arena of['sunny-pond','bathhouse','toyshop']){const old=spring(true,arena),r=spring(false,arena);assert.ok(r.escapedAt!==undefined&&r.escapedAt<6,JSON.stringify(r));assert.ok(old.escapedAt===undefined||r.escapedAt<old.escapedAt);assert.ok(r.nav.recoveries>0);}});
test('eight independently trapped CPUs escape with exactly five fresh presses and intervening releases',()=>{const old=bubble(true),r=bubble(false,8);assert.ok(old.escapedAt.every(x=>x===null));assert.deepEqual(r.edges,Array(8).fill(5));assert.deepEqual(r.releases,Array(8).fill(4));assert.ok(r.escapedAt.every(x=>x!==null&&x<1.2));assert.deepEqual(r.actions,Array(8).fill(0));});
test('early outside pop/expiration, countdown, freeze and new bubble identities do not leave escape held',()=>{const s=session('classic',2),c=s.cs[0],f=s.sim.frogs[0];f.bubbleId=7;const values=Array.from({length:25},(_,t)=>c.input(f,t,true,false,true,s.sim).held);assert.ok(values.includes(true)&&values.includes(false));f.bubbleId=undefined;assert.equal(c.input(f,25,true,false,false,s.sim).held,false);const next=c.input(f,26,true,false,false,s.sim);assert.ok([-1,0,1].includes(next.x));assert.deepEqual(c.input(f,27,false,false,true,s.sim),{x:0,y:0,held:false});assert.deepEqual(c.input(f,28,true,true,true,s.sim),{x:0,y:0,held:false});f.bubbleId=8;assert.equal(c.input(f,29,true,false,true,s.sim).held,false);});
test('bubble expiration in authoritative simulation releases CPU and normal navigation resumes',()=>{const s=session('classic',2),sim=s.sim;applyChaos(sim,['bubble_trouble']);const st=sim.frogChaos.capture()!;st.bubbles=[{id:9,x:12,y:16,born:0,captured:-358,slot:0,presses:0}];sim.frogs[0].bubbleId=9;sim.frogChaos.restore(st);for(let i=0;i<120;i++)s.step();assert.equal(sim.frogs[0].bubbleId,undefined);assert.ok(s.cs[0].tactics.stats.decisions>0);});
test('focused correction changes CPU policy only; approved shared systems stay byte-identical',()=>{const m=JSON.parse(readFileSync('docs/bot-b2s-preservation.json','utf8')),hash=(s:any)=>createHash('sha256').update(s).digest('hex');for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256);assert.equal(hash(readFileSync(p)),r.afterSha256,p);}for(const[p,h]of Object.entries(m.protected))assert.equal(hash(readFileSync(p)),h,p);for(const p of['server/cpu.ts','server/strategy/tactics.ts','server/navigation/navigator.ts'])assert.doesNotMatch(readFileSync(p,'utf8'),/setTransform|setLinearVelocity|applyLinearImpulse|\.infect\(|\.launch\(/);});

