import {b2rPreservedSource} from './preserved-source';
import {test} from 'node:test';import assert from 'node:assert/strict';import {Vec2,Box} from 'planck';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
import {session} from '../scripts/bot-b2-harness';import {frogBodyContacts as requireContacts} from '../server/outbreak-room';import {tacticalState} from '../server/strategy/state';import {FreezeRules} from '../src/game/freeze-tag';import {ClassicRules} from '../src/game/classic-tag';import {OutbreakRules} from '../src/game/outbreak';
function flat(mode:'poison'|'freeze'|'classic',n=4){const s=session(mode,n);for(let b=s.sim.world.getBodyList();b;){const next=b.getNext();if(!s.sim.frogs.some(f=>f.body===b))s.sim.world.destroyBody(b);b=next;}s.sim.world.createBody(Vec2(20,20)).createFixture(Box(20,.5));s.sim.frogs.forEach((f,i)=>f.body.setTransform(Vec2(5+i*4,19),0));return s;}
function decide(s:ReturnType<typeof session>,i:number){const c=s.cs[i];c.input(s.sim.frogs[i],s.sim.tick,true,s.rules instanceof FreezeRules&&s.rules.frozen[i],false,s.sim,tacticalState(s.rules.view(s.sim.tick)));return c.tactics;}
test('Poison pursues safe participants and safe frogs choose separation',()=>{const s=flat('poison');const a=decide(s,0),b=decide(s,1);assert.equal(a.intent,'pursue');assert.equal(a.target,1);assert.equal(b.intent,'evade');assert.ok(b.goal!.x>9);assert.ok(s.cs[0].navigation.goal);});
test('real contact infects, tongue attachment alone does not, and roles retarget immediately',()=>{const s=flat('poison');decide(s,0);const r=s.rules as OutbreakRules;s.sim.frogs[1].body.setTransform(Vec2(5.8,19),0);for(let i=0;i<6;i++)s.step();assert.notEqual(r.records[1].infectedTick,null);assert.equal(decide(s,1).intent,'pursue');assert.notEqual(decide(s,0).target,1);const old=r.records[2].infectedTick;r.infect(s.sim.tick,[]);assert.equal(r.records[2].infectedTick,old);});
test('Freeze freezer excludes frozen targets; runner selects a viable rescue',()=>{const s=flat('freeze'),r=s.rules as FreezeRules;s.sim.frogs[0].body.setTransform(Vec2(30,19),0);s.sim.frogs[1].body.setTransform(Vec2(5,19),0);s.sim.frogs[2].body.setTransform(Vec2(8,19),0);r.records[2].frozen=true;const rescuer=decide(s,1);assert.equal(rescuer.intent,'rescue');assert.equal(rescuer.target,2);assert.notEqual(decide(s,0).target,2);assert.deepEqual(s.cs[2].input(s.sim.frogs[2],0,true,true,false,s.sim,tacticalState(r.view(0))),{x:0,y:0,held:false});});
test('Freeze rescue uses real movement and contact, and danger cancels the rescue goal',()=>{const s=flat('freeze'),r=s.rules as FreezeRules;s.sim.frogs[0].body.setTransform(Vec2(33,19),0);s.sim.frogs[1].body.setTransform(Vec2(5,19),0);s.sim.frogs[2].body.setTransform(Vec2(8,19),0);s.sim.frogs[3].body.setActive(false);r.presence.set(3,false,0,true);r.records[2].frozen=true;let rescued=false;for(let t=0;t<180;t++){s.step();if(!r.records[2].frozen){rescued=true;break;}}assert.ok(rescued);assert.ok(r.records[1].rescues>0);assert.equal(decide(s,2).intent,'evade');r.records[2].frozen=true;s.sim.frogs[0].body.setTransform(Vec2(6,19),0);s.sim.tick+=16;assert.equal(decide(s,1).intent,'evade');});
test('Classic role transfer changes tactical roles and respects the existing global protection',()=>{const s=flat('classic'),r=s.rules as ClassicRules;assert.equal(decide(s,0).intent,'pursue');r.infect(1,[[0,1]]);s.sim.tick=1;assert.equal(r.it,1);assert.equal(decide(s,0).intent,'evade');assert.equal(decide(s,1).intent,'wait');assert.equal(s.cs[1].tactics.target,undefined);s.sim.tick=r.protectedUntil;assert.equal(decide(s,1).intent,'pursue');});
test('target commitment prevents rapid switching; identity/kind is absent from public tactical state',()=>{const s=flat('poison');const t=decide(s,0);let switches=0,last=t.target;for(let i=1;i<=120;i++){s.sim.tick=i;s.sim.frogs[1].body.setTransform(Vec2(9+Math.sin(i)*.1,19),0);decide(s,0);if(t.target!==last)switches++;last=t.target;}assert.ok(switches<=1);const state=tacticalState(s.rules.view(120));assert.ok(!JSON.stringify(state).includes('cpu'));assert.ok(!('patientZeroOrder'in state));assert.ok(!('input'in state.players[0]));});
test('tactical goal updates retain the B1 action plan and never directly move bodies',()=>{const s=flat('poison'),c=s.cs[0],nav=c.navigation;nav.setDestination({x:9,y:19});(nav as any).mode='hold';const positions=s.sim.frogs.map(f=>({...f.body.getPosition()}));c.tactics.update(s.sim,0,tacticalState(s.rules.view(0)),nav);assert.equal((nav as any).mode,'hold');assert.deepEqual(s.sim.frogs.map(f=>({...f.body.getPosition()})),positions);for(const p of['tactics','state'])assert.doesNotMatch(readFileSync(new URL('../server/strategy/'+p+'.ts',import.meta.url),'utf8'),/setTransform|setLinearVelocity|applyForce|applyLinearImpulse|\.infect\(|\.launch\(|\.fire\(/);});
test('restricted phases suspend decisions; reset clears commitments for next round/rematch',()=>{const s=flat('classic'),c=s.cs[0];decide(s,0);const n=c.tactics.stats.decisions;for(let i=0;i<200;i++)c.input(s.sim.frogs[0],i,false,false,false,s.sim,tacticalState(s.rules.view(i)));assert.equal(c.tactics.stats.decisions,n);c.reset();assert.equal(c.tactics.target,undefined);assert.equal(c.navigation.goal,undefined);});
test('B2 preserves exact B1 navigation and all approved physics, modes, modifiers and mobile sources',()=>{const m=JSON.parse(readFileSync(new URL('../docs/bot-b2-preservation.json',import.meta.url),'utf8')),hash=(x:string|Buffer)=>createHash('sha256').update(x).digest('hex');for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(b2rPreservedSource(p)),r.afterSha256,p);}for(const[p,h]of Object.entries(m.protected))assert.equal(hash(b2rPreservedSource(p)),h,p);assert.ok(m.protected['server/navigation/navigator.ts']);});
test('AI frog-grapple attachment does not transmit poison without body contact',()=>{const s=flat('poison',3),r=s.rules as OutbreakRules;s.sim.frogs[0].body.setTransform(Vec2(4,14),0);s.sim.frogs[1].body.setTransform(Vec2(10,8),0);s.sim.frogs[2].body.setTransform(Vec2(35,19),0);let observed=false;for(let i=0;i<90;i++){const state=tacticalState(r.view(s.sim.tick));s.sim.setInput(0,s.cs[0].input(s.sim.frogs[0],s.sim.tick,true,false,false,s.sim,state));s.sim.step();r.infect(s.sim.tick,(requireContacts(s.sim)));const f=s.sim.frogs[0];if(f.tongue?.target===s.sim.frogs[1].body&&Math.hypot(f.body.getPosition().x-s.sim.frogs[1].body.getPosition().x,f.body.getPosition().y-s.sim.frogs[1].body.getPosition().y)>1){assert.equal(r.records[1].infectedTick,null);observed=true;break;}}assert.ok(observed);});
test('tactics remain safe under all modifiers and three modes with eight CPUs',async()=>{const{MODIFIERS,applyChaos}=await import('../src/chaos/registry');for(const mode of['poison','freeze','classic']as const)for(const m of MODIFIERS){const s=session(mode,8);applyChaos(s.sim,[m.id]);for(let i=0;i<120;i++)s.step();for(const f of s.sim.frogs)assert.ok(Number.isFinite(f.body.getPosition().x+f.body.getPosition().y));}});
